# ================================================================ Data Representation

DATA_A = exam("data-representation", "A",
    "Binary, denary and hexadecimal conversions, binary addition and overflow, units, ASCII and Unicode, image file sizes and sound.", [
    boxes("Convert each 8-bit binary number to denary.", [("0010 1101 =", "45"), ("1000 0001 =", "129"), ("1111 0000 =", "240")], numeric=True,
          model="0010 1101 = 32 + 8 + 4 + 1 = 45. 1000 0001 = 128 + 1 = 129. 1111 0000 = 128 + 64 + 32 + 16 = 240.", label="1"),
    boxes("Convert each denary number to an 8-bit binary number.", [("77 =", ["01001101"]), ("200 =", ["11001000"])],
          model="77 = 64 + 8 + 4 + 1 = 0100 1101. 200 = 128 + 64 + 8 = 1100 1000.", label="2"),
    boxes("Convert each binary number to hexadecimal.", [("1010 1111 =", ["AF"]), ("0011 1100 =", ["3C"])],
          model="Split into nibbles: 1010 is A and 1111 is F, giving AF. 0011 is 3 and 1100 is C, giving 3C.", label="3"),
    ans("Convert the hexadecimal number 2B to denary.", "43", numeric=True, model="2 x 16 + 11 = 43.", width=6, label="4"),
    tick("Why do programmers use hexadecimal?",
         ["*It is shorter and easier for people to read than binary", "Computers store data in hexadecimal", "It uses less memory", "It is more accurate than binary"],
         "Each hex digit stands for four bits, so values are shorter and fewer mistakes are made. The computer still stores binary.", label="5"),
    ans("Add these two 8-bit binary numbers. Give your answer in binary.\n\n0101 1010 + 0011 0110", ["10010000"],
        model="90 + 54 = 144, which is 1001 0000.", width=10, label="6"),
    tick("What is overflow?",
         ["*When the result of a calculation is too large to fit in the bits available", "When a file is too big for memory",
          "When the CPU overheats", "When a number is negative"],
         "An 8-bit result above 255 cannot be stored: that is overflow.", label="7"),
    ans("1100 0000 + 1000 0000 overflows when stored in 8 bits. What is the true answer in denary?", "320", numeric=True,
        model="192 + 128 = 320, which is more than 255.", width=6, label="8"),
    rows("Tick one box in each row.", ["Bit", "Nibble", "Byte", "Kilobyte"],
         [("4 bits", "Nibble"), ("8 bits", "Byte"), ("A single 0 or 1", "Bit"), ("1000 bytes", "Kilobyte")],
         model="A bit is one binary digit, a nibble is 4 bits, a byte is 8 bits and a kilobyte is 1000 bytes.", label="9"),
    tick("Why was Unicode created when ASCII already existed?",
         ["*ASCII cannot represent the characters of every language, or emoji", "ASCII is too slow", "Unicode uses fewer bits", "ASCII only stores numbers"],
         "ASCII has room for 128 characters. Unicode has room for every writing system.", label="10"),
    ans("In ASCII, A is 65. What is the code for E?", "69", numeric=True, model="E is four letters after A: 65 + 4 = 69.", width=4, label="11"),
    calc("An image is 200 pixels wide and 100 pixels high, with a colour depth of 8 bits. Calculate the file size in bytes. Show your working.",
         "20000", 3, [("Multiplies the width by the height", ["200 x 100", "200*100", "200 × 100", "20000 pixels", "20,000 pixels", "20000"]),
                      ("Multiplies by the colour depth, then divides by 8 to turn bits into bytes", ["x 8", "*8", "× 8", "160000", "160,000", "/ 8", "/8", "divide by 8", "÷ 8"])],
         model="200 x 100 = 20,000 pixels. 20,000 x 8 bits = 160,000 bits. 160,000 / 8 = 20,000 bytes.", unit="bytes", label="12"),
    tick("What happens to an image's file size if its colour depth is increased?",
         ["*It increases, because more bits are stored for every pixel", "It decreases", "It stays the same", "The image loses pixels"],
         "More bits per pixel means more bits overall.", label="13"),
    write("Explain how increasing the sample rate affects a sound file.", 2, [
        ("More samples are taken each second, so the recording is closer to the original sound", ["more samples", "closer", "accurate", "better quality", "detail"]),
        ("The file size increases", ["bigger", "larger", "file size", "more storage", "more data"]),
    ], "A higher sample rate takes more measurements every second, so the recording follows the original sound more closely and sounds better. Each sample has to be stored, so the file gets bigger.",
          command="Explain", label="14"),
    tick("What is metadata in an image file?",
         ["*Data about the image, such as its width, height and colour depth", "The colours of the pixels", "A copy of the image", "A smaller version of the image"],
         "Metadata describes the file so it can be displayed correctly.", label="15"),
])

